# DK KEV.  Kolding - Egtved
#
let kk = path("d3.dk.kev.1");
let ke = path("d3.dk.kev.2");

with detail = 3, railway = :third :narrow:g1000 :pax :removed {
    # point.dk.Kolding  dk.FPB

    with link = "line.dk.KEV" {
        track(:station,
                kk[:kol.yt - 0.1dl, :kol.yt] << 0.5md << 1ms << 1mt >> 0.5lt
            ..  kk[:kol.xt, :kol.xt + 0.1dl]
        );
        track(:ror, kk[:kol.xt, :kon.ye + 0.1dl]);
    }

    with link = "point.dk.Kolding-Nord", railway = :station {
        track(kk[:kon.ye, :kon + 0.5sw]);
        marker(:left :de.bf, kk[:kon] << 0.5lt);
        slabel(:left, kk[:kon] >> 0.5lt + (0.5dt, -0.8dt),
            vbox(:right:base, "Kolding ", "Nord")
        );
    }

    with link = "line.dk.KEV" {
        track(:ror, ke[:kon.ye, :kon.ze]);
        track(ke[:kon.ze - 0.1dl, :kon.ze + 2.11km]);
        line_label(:left:e, ke[:kon.ze + 2.1km] << 0.5lt,
            (0dt, 0.1dt), "KEV"
        );
        track(ke[:kon.ze + 2.09km, :brm + 0.1dl]);
    }

    with link = "point.dk.Bramdrup", railway = :station {
        track(ke[:brm, :brm + 1sw]);
        marker(:left :de.hst :casing, ke[:brm + 0.5sw] << 0.5lt);
        slabel(:right, ke[:brm] >> 0.5lt + (1.5dt, 0dt), "Bramdrup");
    }

    with link = "line.dk.KEV" {
        track(ke[:brm + 0.99sw, :lil - 0.49sw]);
    }

    with link = "point.dk.Lilballe", railway = :station {
        track(ke[:lil - 0.5sw, :lil + 0.5sw]);
        marker(:right :de.hst, ke[:lil] >> 0.5lt);
        slabel(:right, ke[:lil] >> 0.5lt >> 1sh + (1.3dt, 1.3dt),
            "Lilballe"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:lil + 0.49sw, :alm - 0.49sw]);
    }

    with link = "point.dk.Alminde", railway = :station {
        track(ke[:alm - 0.5sw, :alm + 0.5sw]);
        marker(:left :de.bf, ke[:alm] << 0.5lt);
        slabel(:left, ke[:alm] << 0.5lt << 1sh + (-1.3dt, 0.8dt),
            "Alminde"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:alm + 0.49sw, :alm + 1.41km]);
        line_label(:right:nw, ke[:alm + 1.4km] >> 0.5lt, "KEV");
        track(ke[:alm + 1.39km, :hau - 0.49sw]);
    }

    with link = "point.dk.Hauerballe", railway = :station {
        track(ke[:hau - 0.5sw, :hau + 0.5sw]);
        marker(:right :de.hst, ke[:hau] >> 0.5lt);
        slabel(:right, ke[:hau] >> 0.5lt >> 1sh + (1.3dt, 0.8dt),
            "Hauerballe"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:hau + 0.49sw, :eli - 0.49sw]);
    }

    with link = "point.dk.Elisabethsminde", railway = :station {
        track(ke[:eli - 0.5sw, :eli + 0.5sw]);
        marker(:right :de.hp, ke[:eli] >> 0.5lt);
        slabel(:right, ke[:eli] >> 0.5lt >> 1sh + (1.3dt, 0.8dt),
            "Elisabethsminde"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:eli + 0.49sw, :viu - 0.49sw]);
    }

    with link = "point.dk.Viuf", railway = :station {
        track(ke[:viu - 0.5sw, :viu + 0.5sw]);
        marker(:right :de.bf, ke[:viu] >> 0.5lt);
        slabel(:right, ke[:viu] >> 0.5lt >> 1sh + (1.5dt, 0.3dt),
            "Viuf"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:viu + 0.49sw, :dau - 0.49sw]);
    }

    with link = "point.dk.Daugårdsmindevejen", railway = :station {
        track(ke[:dau - 0.5sw, :dau + 0.5sw]);
        marker(:right :de.hp, ke[:dau] >> 0.5lt);
        slabel(:right, ke[:dau] >> 0.5lt >> 1sh + (1.2dt, -0.3dt),
            "Daugårdsmindevejen"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:dau + 0.49sw, :sta - 0.49sw]);
    }

    with link = "point.dk.Starup", railway = :station {
        track(ke[:sta - 0.5sw, :sta + 0.5sw]);
        marker(:right :de.hst, ke[:sta] >> 0.5lt);
        slabel(:left, ke[:sta] << 0.5lt + (-1.2dt, 2.0dt),
            "Starup"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:sta + 0.49sw, :ski - 0.49sw]);
    }

    with link = "point.dk.Starup-Kirkevej", railway = :station {
        track(ke[:ski - 0.5sw, :ski + 0.5sw]);
        marker(:right :de.hp, ke[:ski] >> 0.5lt);
        slabel(:right, ke[:ski] >> 0.5lt >> 1sh + (1.3dt, 0dt),
            "Starup Kirkevej"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:ski + 0.49sw, :gra - 0.49sw]);
    }

    with link = "point.dk.Gravens", railway = :station {
        track(ke[:gra - 0.5sw, :gra + 0.5sw]);
        marker(:right :de.bf, ke[:gra] >> 0.5lt);
        slabel(:top, ke[:gra] >> 0.5lt >> 1sh + (3dt, -0.3dt),
            "Gravens"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:gra + 0.49sw, :bsk - 0.49sw]);
    }

    with link = "point.dk.Brakker-Skovvej", railway = :station {
        track(ke[:bsk - 0.5sw, :bsk + 0.5sw]);
        marker(:right :de.hp, ke[:bsk] >> 0.5lt);
        slabel(:left, ke[:bsk] >> 0.5lt >> 1sh + (2.8dt, -1dt),
            vbox(:center:base, "Brakker", "Skovvej")
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:bsk + 0.49sw, :brk - 0.49sw]);
    }

    with link = "point.dk.Brakker", railway = :station {
        track(ke[:brk - 0.5sw, :brk + 0.5sw]);
        marker(:left :de.hst, ke[:brk] << 0.5lt);
        slabel(:bottom, ke[:brk] << 0.5lt << 1sh << 0.3dt,
            "Brakker"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:brk + 0.49sw, :mol - 0.49sw]);
    }

    with link = "point.dk.Mølkjærs-Gård", railway = :station {
        track(ke[:mol - 0.5sw, :mol + 0.5sw]);
        marker(:right :de.hp, ke[:mol] >> 0.5lt);
        guide(:removed,
                ke[:mol] >> 0.5lt >> 1sh >> 0.5dt
            --  ke[:mol] + (-3dt, -12dt)
        );
        slabel(:top, ke[:mol] + (-3dt, -12.3dt),
            "Mølkjærs Gård"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:mol + 0.49sw, :ven - 0.49sw]);
    }

    with link = "point.dk.Venborgvej", railway = :station {
        track(ke[:ven - 0.5sw, :ven + 0.5sw]);
        marker(:right :de.hp, ke[:ven] >> 0.5lt);
        guide(:removed,
                ke[:ven] >> 0.5lt >> 1sh >> 0.5dt
            --  ke[:ven] + (-2.5dt, -9dt)
        );
        slabel(:left, ke[:ven] + (0dt, -10dt),
            "Venborgvej"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:ven + 0.49sw, :bol - 0.49sw]);
    }

    with link = "point.dk.Bølling", railway = :station {
        track(ke[:bol - 0.5sw, :bol + 0.5sw]);
        marker(:left :de.hst, ke[:bol] << 0.5lt);
        slabel(:bottom, ke[:bol] << 0.5lt << 1sh << 0.3dt,
            "Bølling"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:bol + 0.49sw, :hje - 0.49sw]);
    }

    with link = "point.dk.Hjelmdrupvej", railway = :station {
        track(ke[:hje - 0.5sw, :hje + 0.5sw]);
        marker(:left :de.hp, ke[:hje] << 0.5lt);
        slabel(:left, ke[:hje] << 0.5lt << 1sh + (2.5dt, 3.5dt),
            "Hjelmdrupvej"
        );
    }

    with link = "line.dk.KEV" {
        track(ke[:hje + 0.49sw, :hje + 1.51km]);
        line_label(:left:ne, ke[:hje + 1.5km] << 0.5lt, "KEV");
        track(ke[:hje + 1.49km, :egt - 0.49sw]);
    }

    with link = "point.dk.Egtved", railway = :station {
        track(ke[:egt - 0.5sw, :egt + 0.5sw]);
        marker(:right :de.bf, ke[:egt] >> 0.5lt);
        slabel(:top, ke[:egt] >> 0.5lt >> 1sh + (-0.5dt, -0.3dt),
            span(:bold, "Egtved")
        );
    }
}

